func persistVerifiedSearchSnapshot(
	ctx context.Context,
	entry cacheEntry,
	cache cachedSearchSnapshot,
	readPersistedDigest func(cacheEntry) (cacheDigest, error),
) error {
	var verifyErr error
	for attempt := 0; attempt < 2; attempt++ {
