			symbol: StoreContextSymbol{
				ID:            id,
				Name:          name,
				QualifiedName: qualified,
				Kind:          kind,
				FilePath:      filePath,
				StartLine:     full.StartLine,
				EndLine:       full.EndLine,
				Signature:     full.Signature,
				Language:      full.Language,
