var ancestorTestChangedFiles = []string{"doomed.go", "gadget.go", "new_name.go", "old_name.go"}

func refusalReason(err error) string {
	var refusal *ancestorStoreRefusal
	if errors.As(err, &refusal) {
		return refusal.reason
	}
	return ""
