	})

	t.Run("ignore policy mismatch", func(t *testing.T) {
		repo := ancestorTestRepo(t)
		cacheDir := t.TempDir()
		ancestorTestBuildStore(t, repo, cacheDir, ancestorTestVersion, ancestorTestOptions)
		ancestorTestRefactorCommit(t, repo)
